      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "U5: GF Source Native Authentication",
      "activity_description": "Enable native GemFire authentication for the GF source and document the required security properties.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "U6: jdbcgpfdist Batch Job Implementation",
