      "activity_name": "U8: Reactor Data Processor Migration",
      "activity_description": "Move the project reactor based data processor module from the spring-xd-module repo to the core repository.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A10",
      "activity_name": "Testing & QA",
